cardCss:
.jgo-card {
    background: var(--card-bg, #ffffff);
    border-radius: 18px;
    padding: 22px 28px 18px;
    box-shadow: 0 1px 3px rgba(30,41,59,.10), 0 8px 24px rgba(30,41,59,.08);
    border: 1px solid var(--line, #e6e9f0);
    border-top: 4px solid #4f6bed;
    min-height: 260px;
    display: flex; flex-direction: column;
    font-family: "Hiragino Sans","Hiragino Kaku Gothic ProN","Noto Sans JP","Yu Gothic","PingFang SC",sans-serif;
}
.jgo-row {
    display: inline-flex; align-items: center; gap: 8px;
    align-self: flex-start;
    background: #eef1ff; color: #4f6bed;
    font-size: calc(13px * var(--card-font-scale,1));
    font-weight: 700;
    padding: 4px 12px; border-radius: 999px;
    margin-bottom: 8px;
}
.jgo-kana {
    display: flex; align-items: center; justify-content: center;
    gap: 30px; margin: 4px 0; flex: 1; flex-wrap: wrap;
}
.jgo-kana-block { text-align: center; }
.jgo-hira, .jgo-kata { line-height: 1.1; color: #1e293b; font-weight: var(--card-font-weight, 700); }
.jgo-hira { font-size: calc(76px * var(--card-font-scale,1)); }
.jgo-kata { font-size: calc(42px * var(--card-font-scale,1)); color: #4f6bed; }
.jgo-kana-label {
    font-size: calc(11px * var(--card-font-scale,1));
    color: #94a3b8; margin-top: 4px; letter-spacing: 2px;
}
.jgo-romaji {
    text-align: center;
    font-size: calc(22px * var(--card-font-scale,1));
    font-weight: 700; color: #334155; letter-spacing: 3px;
    margin: 2px 0 10px;
}
.jgo-example {
    border-top: 1px dashed var(--line, #e6e9f0);
    padding-top: 10px; margin-top: auto;
    font-size: calc(14px * var(--card-font-scale,1));
    color: #475569; line-height: 1.5;
}
.jgo-example .jgo-ex-word { color: #4f6bed; font-weight: 700; }
.jgo-tools { display: flex; gap: 6px; margin-top: 12px; }
.jgo-tools .action-btn { width: 38px; height: 38px; border: none; background: var(--action-btn-bg, #eef1ff); border-radius: 90px; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #4f6bed; transition: all .2s; }
.jgo-tools .action-btn:hover { background: #dfe5ff; }
.jgo-tools .action-btn.is-active { background: #4f6bed; color: #fff; }

.action-btn i { font-size: 18px; line-height: 1; }
.action-btn:hover i { transform: scale(1.1); }

.jgo-card { margin-bottom: 16px; }

.jgo-top { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 8px; }
.jgo-top .jgo-tools { margin-top: 0; }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    window.cardTemplate = {
        name: '日语五十音图',
        fields: [
            { key: 'hiragana', label: '平假名', hideable: false },
            { key: 'katakana', label: '片假名', hideable: false },
            { key: 'romaji',   label: '罗马字' },
            { key: 'row',      label: '行' },
            { key: 'example',  label: '例词' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function wrap(k, html) { return isHidden(k) ? '' : html; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            var exampleHtml = '';
            if (d.example) {
                var m = String(d.example).match(/^(.*?)[（(](.*)[）)]$/);
                var word = m ? m[1] : d.example;
                var mean = m ? m[2] : '';
                exampleHtml = '<div class="jgo-example">例：<span class="jgo-ex-word">' + esc(word) + '</span>'
                    + (mean ? '（' + esc(mean) + '）' : '') + '</div>';
            }
            return '<div class="jgo-card" data-card-id="' + data.id + '">' +
                '<div class="jgo-top">' +
                    wrap('row', '<span class="jgo-row">' + esc(d.row || '') + ' 行</span>') +
                    '<div class="jgo-tools">' +
                        '<button class="action-btn act-play" data-action="play" data-tooltip="朗读"><i class="fa-solid fa-volume-high"></i></button>' +
                        '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="标记"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>' +
                        '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>' +
                    '</div>' +
                '</div>' +
                '<div class="jgo-kana">' +
                    wrap('hiragana', '<div class="jgo-kana-block"><div class="jgo-hira">' + esc(d.hiragana) + '</div><div class="jgo-kana-label">平假名</div></div>') +
                    wrap('katakana', '<div class="jgo-kana-block"><div class="jgo-kata">' + esc(d.katakana) + '</div><div class="jgo-kana-label">片假名</div></div>') +
                '</div>' +
                wrap('romaji', '<div class="jgo-romaji">' + esc(d.romaji) + '</div>') +
                wrap('example', exampleHtml) +
            '</div>';
        },
        init: function (el, cardData, api) {
            var playBtn = el.querySelector('[data-action="play"]');
            if (playBtn) playBtn.addEventListener('click', function () {
                var d = (cardData && cardData.data) || {};
                api.playAudio(d.hiragana || d.romaji || '');
                api.track('audio_play');
            });
            var markBtn = el.querySelector('[data-action="mark"]');
            if (markBtn) markBtn.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = el.querySelector('[data-action="favorite"]');
            if (favBtn) favBtn.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
        }
    };
})();
